@include deprecate('4.0.0', 'Please use slds-tabs_scoped__item instead') {

  .slds-tabs_scoped,
  .slds-tabs--scoped {

    .slds-tabs__item {
      position: relative;
      margin-bottom: ($border-width-thin * -1);

      + .slds-tabs__item {
        margin-left: ($border-width-thin * -1);
      }

      &:first-child > a {
        border-left: 0;
        border-radius: $border-radius-medium 0 0 0;
      }

      > a {
        @include tabs-link;
        height: $line-height-tab;
        line-height: $line-height-tab;
        padding: 0 $spacing-large;
        color: var(--slds-g-color-neutral-base-30, #{$color-text-weak});
        background-clip: padding-box;
        border-left: $border-width-thin solid transparent;
        border-right: $border-width-thin solid transparent;

        &:hover,
        &:focus {
          text-decoration: none;
          color: var(--slds-g-link-color-hover, #{$color-text-link-hover});
          border-color: var(--slds-g-color-border-base-4, #{$color-border});
        }
      }
      // scss-lint:disable SelectorDepth
      .slds-active > a {
        background-color: var(--slds-g-color-neutral-base-100, #{$color-background-alt});
        color: var(--slds-g-link-color, #{$color-text-link});
        border-color: var(--slds-g-color-border-base-4, #{$color-border});

        &:focus {
          text-decoration: underline;
        }
      }
    }

    > .slds-tabs__content {
      background-color: var(--slds-g-color-neutral-base-100, #{$color-background-alt});
      border: $border-width-thin solid var(--slds-g-color-border-base-4, #{$color-border-button-default});
      border-top: 0;
      border-radius: 0 0 $border-radius-medium $border-radius-medium;
      padding: $spacing-medium;
    }
  }
}
